SELECT EXISTS(SELECT 1 FROM core_import_rows s JOIN core_transactions t ON t.company_id=$2 AND t.account_id=$3 AND t.source_system='dataset_v1' AND t.source_company_id=$4 AND t.external_id=s.external_id WHERE s.import_id=$1 AND(s.operation_date<>t.operation_date OR s.amount_minor<>t.amount_minor OR s.direction<>t.direction OR s.payload->>'INN'<>t.counterparty_inn OR s.payload->>'Name'<>t.counterparty_name OR s.payload->>'Purpose'<>t.purpose)) OR EXISTS(SELECT 1 FROM core_import_rows s JOIN core_balances b ON b.company_id=$2 AND b.account_id=$3 AND b.balance_date=s.operation_date WHERE s.import_id=$1 AND(s.balance_minor<>b.amount_minor OR (b.source_kind='statement_eod' AND (b.source_system IS DISTINCT FROM 'dataset_v1' OR b.source_company_id IS DISTINCT FROM $4))));
